import{_ as e,c as a,o as r,b0 as l}from"./chunks/framework.BpbtKNwe.js";const s="/aillm-docs/assets/a99533d0a1ffdfe437233ab997b73f61.DhjBCZDj.svg",o="/aillm-docs/assets/system-diagram-light.BDURDXZ7.png",n="/aillm-docs/assets/milvus_architecture_2_6.Cy_qv7LL.png",i="/aillm-docs/assets/0e8c157342231fbdb50c100761195f5d.9Dvp_GRB.svg",d="/aillm-docs/assets/67781ab1bf3e90bd49b2405bf23681d7.DcaW1qrc.svg",_=JSON.parse('{"title":"LV015-向量数据库","description":null,"frontmatter":{"title":"LV015-向量数据库","date":"2025-11-28T19:54:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/llm/rag/126b154d697107f0ae9f9094","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-28T19:54:41.127Z","fulluuid":"0ae9f9094bbb43a29c21c7c252f6bcaf","useduuid":"0ae9f9094"}},"headers":[],"relativePath":"sdoc/llm/rag/126b154d697107f0ae9f9094.md","filePath":"sdoc/05-LLM/06-RAG/LV015-向量数据库.md","lastUpdated":1767430713000}'),c={name:"sdoc/llm/rag/126b154d697107f0ae9f9094.md"};function g(h,t,f,p,m,u){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="lv015-向量数据库" tabindex="-1">LV015-向量数据库 <a class="header-anchor" href="#lv015-向量数据库" aria-label="Permalink to &quot;LV015-向量数据库&quot;">​</a></h1><p>向量数据库是 RAG 系统的“语义底座”，使用什么数据库决定检索质量与系统可扩展性。</p><p>向量数据库在 RAG（Retrieval-Augmented Generation, 检索增强生成）系统中承担了向量化后的文本、图像、代码等数据的高效存储与近邻检索。实际工程中，向量数据库的选则直接影响系统性能、成本和后续扩展能力。</p><h2 id="一、rag-系统中的向量数据库" tabindex="-1">一、RAG 系统中的向量数据库 <a class="header-anchor" href="#一、rag-系统中的向量数据库" aria-label="Permalink to &quot;一、RAG 系统中的向量数据库&quot;">​</a></h2><p><img src="'+s+'" alt="图 1: RAG 系统中的向量数据库位置"></p><p>如图所示，向量数据库位于 <strong>Embedding 输出</strong> 与 <strong>Context 构建</strong> 之间，是信息检索质量的核心影响因素。</p><h2 id="二、-常见的数据库" tabindex="-1">二、 常见的数据库 <a class="header-anchor" href="#二、-常见的数据库" aria-label="Permalink to &quot;二、 常见的数据库&quot;">​</a></h2><h3 id="_1-可以选择哪些数据库啊" tabindex="-1">1. 可以选择哪些数据库啊？ <a class="header-anchor" href="#_1-可以选择哪些数据库啊" aria-label="Permalink to &quot;1. 可以选择哪些数据库啊？&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">方案</th><th style="text-align:left;">最佳使用场景</th><th style="text-align:left;">优势</th><th style="text-align:left;">局限</th><th style="text-align:left;">典型规模</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Chroma</strong></td><td style="text-align:left;">本地开发、轻量应用、桌面级 RAG</td><td style="text-align:left;">零依赖、好用、迭代快</td><td style="text-align:left;">不适合超大规模/分布式</td><td style="text-align:left;">≤ 100 万向量</td></tr><tr><td style="text-align:center;"><strong>Milvus</strong></td><td style="text-align:left;">企业级集群、十亿向量、多租户</td><td style="text-align:left;">高吞吐、GPU 索引、多副本 HA</td><td style="text-align:left;">运维成本高</td><td style="text-align:left;">1 亿～10 亿向量</td></tr><tr><td style="text-align:center;"><strong>Weaviate</strong></td><td style="text-align:left;">结构化 + 向量混合搜索、知识库</td><td style="text-align:left;">GraphQL、Filter 强、插件丰富</td><td style="text-align:left;">部署复杂度略高</td><td style="text-align:left;">1 百万～5 亿</td></tr><tr><td style="text-align:center;"><strong>PGVector</strong></td><td style="text-align:left;">已经大量使用 PostgreSQL 的团队</td><td style="text-align:left;">无需引入新系统、关系型融合</td><td style="text-align:left;">索引能力弱于专业库</td><td style="text-align:left;">≤ 数百万向量</td></tr><tr><td style="text-align:center;"><strong>Qdrant</strong></td><td style="text-align:left;">高性能、快速落地、云原生</td><td style="text-align:left;">Rust 实现、高并发、实时更新</td><td style="text-align:left;">生态略逊于 Milvus</td><td style="text-align:left;">百万～数亿</td></tr><tr><td style="text-align:center;"><strong>Pinecone（商用）</strong></td><td style="text-align:left;">不希望自运维、想快速上线</td><td style="text-align:left;">托管服务、全托管索引</td><td style="text-align:left;">成本较高、闭源</td><td style="text-align:left;">视套餐而定</td></tr></tbody></table><p>总的来说，轻量用 Chroma，本地用 PGVector，大规模用 Milvus，语义 + 结构搜索用 Weaviate，全托管选 Pinecone，高性能选 Qdrant。</p><h3 id="_2-数据库简介" tabindex="-1">2. 数据库简介 <a class="header-anchor" href="#_2-数据库简介" aria-label="Permalink to &quot;2. 数据库简介&quot;">​</a></h3><h4 id="_2-1-chroma" tabindex="-1">2.1 Chroma <a class="header-anchor" href="#_2-1-chroma" aria-label="Permalink to &quot;2.1 Chroma&quot;">​</a></h4><p><a href="https://docs.trychroma.com/docs/overview/introduction" target="_blank" rel="noreferrer">Chroma</a> <strong>是开源的 AI 应用数据库</strong>。Chroma 通过让知识、事实和技能可作为大模型的插件，使构建大模型应用变得简单。</p><p>Chroma 采用模块化架构设计，注重性能和易用性。它能从本地开发无缝扩展到大规模生产环境，同时在所有部署模式下提供一致的 API。无论采用何种部署模式，Chroma 都由五个核心组件构成。每个组件在系统中都扮演着独特的角色，并基于共享的 <a href="https://docs.trychroma.com/docs/overview/data-model" target="_blank" rel="noreferrer">Chroma 数据模型</a> 运行。</p><p><img src="'+o+'" alt="Chroma System architecture"></p><blockquote><p>更深入的了解可以看官网文档：<a href="https://docs.trychroma.com/docs/overview/introduction" target="_blank" rel="noreferrer">Introduction - Chroma Docs</a></p></blockquote><h4 id="_2-2-milvus-分布式架构" tabindex="-1">2.2 Milvus（分布式架构） <a class="header-anchor" href="#_2-2-milvus-分布式架构" aria-label="Permalink to &quot;2.2 Milvus（分布式架构）&quot;">​</a></h4><p><a href="https://milvus.io/docs/zh" target="_blank" rel="noreferrer">Milvus</a> 是一个 <strong>开源</strong> <strong>云原生</strong> 向量数据库，专为在海量向量数据集上进行高性能相似性搜索而设计。它建立在流行的向量搜索库（包括 Faiss、HNSW、DiskANN 和 SCANN）之上，可为人工智能应用和非结构化数据检索场景提供支持。</p><p>下图说明了 Milvus 的高层架构，展示了其模块化、可扩展和云原生的设计，以及完全分解的存储层和计算层。</p><p><img src="'+n+'" alt="Architecture_diagram"></p><p>Milvus 遵循数据平面和控制平面分解的原则，由四个主要层组成，在可扩展性和灾难恢复方面相互独立。这种共享存储架构具有完全分解的存储层和计算层，可实现计算节点的横向扩展，同时将啄木鸟作为零磁盘 WAL 层实施，以增强弹性并减少操作开销。</p><p>通过将流处理分为流节点（Streaming Node）和批处理分为查询节点（Query Node）和数据节点（Data Node），Milvus 在满足实时处理要求的同时实现了高性能。</p><blockquote><p>更深入的了解可以看官方文档：<a href="https://milvus.io/docs/zh/architecture_overview.md" target="_blank" rel="noreferrer">Milvus 架构概述 | Milvus 文档</a></p></blockquote><h4 id="_2-3-weaviate-模块化插件架构" tabindex="-1">2.3 Weaviate（模块化插件架构） <a class="header-anchor" href="#_2-3-weaviate-模块化插件架构" aria-label="Permalink to &quot;2.3 Weaviate（模块化插件架构）&quot;">​</a></h4><p><a href="https://docs.weaviate.io/weaviate" target="_blank" rel="noreferrer">Weaviate</a> 是一个开源的人工智能向量数据库。擅长多模态检索与结构化数据混合搜索，插件生态丰富。</p><img src="'+i+'" alt="图 3: Weaviate 模块化插件架构" style="zoom:25%;"><p>它的一些基本概念可以看这里：<a href="https://docs.weaviate.io/weaviate/concepts" target="_blank" rel="noreferrer">Concepts | Weaviate Documentation</a></p><h4 id="_2-4-pgvector-关系型融合" tabindex="-1">2.4 PGVector（关系型融合） <a class="header-anchor" href="#_2-4-pgvector-关系型融合" aria-label="Permalink to &quot;2.4 PGVector（关系型融合）&quot;">​</a></h4><p><a href="https://github.com/pgvector/pgvector?tab=readme-ov-file#readme" target="_blank" rel="noreferrer">pgvector</a> 是 Postgres 的开源向量相似度搜索，支持精确和近似最近邻搜索，基本架构如下：</p><p><img src="'+d+'" alt="图 4: PGVector 关系型融合架构"></p><p>PGVector 无需引入额外组件，是最“成本友好”的解决方案，适合小规模或已有 PostgreSQL 资产的场景。</p><h3 id="_3-工程实践中的建议" tabindex="-1">3. 工程实践中的建议 <a class="header-anchor" href="#_3-工程实践中的建议" aria-label="Permalink to &quot;3. 工程实践中的建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">工程点</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>索引选型</strong></td><td style="text-align:left;">Milvus 用 IVF+PQ；Qdrant/Weaviate 用 HNSW；PGVector 优先 HNSW</td></tr><tr><td style="text-align:center;"><strong>Embedding 维度</strong></td><td style="text-align:left;">低维度更快；高维度更准，但更吃内存</td></tr><tr><td style="text-align:center;"><strong>Metadata Filter</strong></td><td style="text-align:left;">所有向量库都支持，但 Weaviate / Qdrant 最强</td></tr><tr><td style="text-align:center;"><strong>多模态检索</strong></td><td style="text-align:left;">Weaviate（最完善）</td></tr><tr><td style="text-align:center;"><strong>可观测性</strong></td><td style="text-align:left;">Milvus、Qdrant 表现最佳</td></tr><tr><td style="text-align:center;"><strong>向量更新频率</strong></td><td style="text-align:left;">Qdrant 更新性能优于 Milvus</td></tr></tbody></table><h3 id="三、总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三、总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h3><p>向量数据库不是“越强越好”，而是应根据预算、团队能力、数据规模、更新频率、部署环境来选择。在 AI Native 系统中，它本质上是：</p><ul><li><strong>语义检索引擎</strong></li><li><strong>上下文质量的决定因素</strong></li><li><strong>RAG 能否扩展到企业级的关键瓶颈点</strong></li></ul><p>合理的选则与调优能使 RAG 系统在准确率、召回率、延迟与成本之间做到最佳平衡。</p>',37)])])}const b=e(c,[["render",g]]);export{_ as __pageData,b as default};
